export function retryJob(ctx: JobsContext, id: string): ApiResponse {
  return transition(ctx, id, "queued", "job:retried", { lastError: undefined });
}

export function pauseJob(ctx: JobsContext, id: string): ApiResponse {
  return transition(ctx, id, "paused", "job:paused");
}

export function resumeJob(ctx: JobsContext, id: string): ApiResponse {
  const job = requireJob(ctx, id);
  if (job.status !== "paused") throw conflict(`job ${id} is ${job.status}, not paused`);
  return transition(ctx, id, "queued", "job:resumed");
}

.add("POST", "/jobs/:id/retry", scoped("jobs:write", (_req, p) => retryJob(ctx, p.id)))
.add("POST", "/jobs/:id/pause", scoped("jobs:write", (_req, p) => pauseJob(ctx, p.id)))
.add("POST", "/jobs/:id/resume", scoped("jobs:write", (_req, p) => resumeJob(ctx, p.id)));
